import{c as a,Q as t,j as l,m as i}from"./chunks/framework.BbINFf4E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"東大数学攻略本","text":"東大数学の過去問から、考え方を学ぶ教材","tagline":"単元暗記ではなく、問題の切り方を身につける","actions":[{"theme":"brand","text":"第1章から読む","link":"/chapter-01"},{"theme":"alt","text":"出典・謝辞","link":"/credits"}]},"features":[{"title":"問題を構造で読む","details":"見た目の単元ではなく、座標化・領域化・状態遷移などの切り方で整理します。"},{"title":"Plan と Do を分ける","details":"いきなり計算に入らず、入口・式化・出口を決めてから解答に進みます。"},{"title":"過去問から手筋を学ぶ","details":"東大数学の過去問を題材に、初見問題への方針の立て方を学びます。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function h(n,e,o,p,c,s){return t(),l("div",null,[...e[0]||(e[0]=[i('<h2 id="章一覧" tabindex="-1">章一覧 <a class="header-anchor" href="#章一覧" aria-label="Permalink to &quot;章一覧&quot;">​</a></h2><ul><li><a href="./chapter-01.html">第1章　座標化・1変数化・最大最小</a></li><li><a href="./chapter-02.html">第2章　領域化・範囲決定</a></li><li><a href="./chapter-03.html">第3章　微積分・面積体積・極限評価</a></li><li><a href="./chapter-04.html">第4章　整数・合同式・場合分け</a></li><li><a href="./chapter-05.html">第5章　確率・状態遷移・漸化式</a></li><li><a href="./chapter-06.html">第6章　関数決定・係数比較・接線条件</a></li><li><a href="./chapter-07.html">第7章　空間図形・断面・体積</a></li><li><a href="./chapter-08.html">第8章　対称性・変換・複素数・行列</a></li><li><a href="./final-chapter.html">最終章　総合演習</a></li></ul><h2 id="この教材について" tabindex="-1">この教材について <a class="header-anchor" href="#この教材について" aria-label="Permalink to &quot;この教材について&quot;">​</a></h2><p>この教材は、東京大学の数学入試問題を題材に、受験生が「問題をどう切るか」を学ぶための教材です。</p><p>単元別の公式暗記ではなく、問題を見た瞬間に</p><ul><li>何を変数にするか</li><li>どの条件を式にするか</li><li>どの手筋で処理するか</li><li>どこを出口にするか</li></ul><p>を考えられるようになることを目標にしています。</p><h2 id="出典・謝辞" tabindex="-1">出典・謝辞 <a class="header-anchor" href="#出典・謝辞" aria-label="Permalink to &quot;出典・謝辞&quot;">​</a></h2><p>本教材の作成にあたり、東京大学数学入試問題の確認・参照において、以下のサイトを参考にしました。</p><ul><li><a href="http://server-test.net/math/tokyo/" target="_blank" rel="noreferrer">東京大学 数学入試問題</a></li></ul><p>貴重な資料を公開されていることに感謝いたします。</p><p>詳しくは <a href="./credits.html">出典・謝辞</a> をご覧ください。</p>',12)])])}const f=a(r,[["render",h]]);export{m as __pageData,f as default};
